const PRIMARY_400 = "var(--color-primary-400, #4ade80)";
const PRIMARY_600 = "var(--color-primary-600, #16a34a)";
const PRIMARY_700 = "var(--color-primary-700, #15803d)";

export interface ToothGlyphProps {
  toothClass: ToothClass;
