/** Occlusal-view outline per tooth class — what a printed odontogram
 *  draws: molars as broad crowns with a cusp cross, premolars with one
 *  groove, canines pointed, incisors narrow. */
function Outline({
  toothClass,
  position,
  fill,
  stroke,
  dashed,
}: {
  toothClass: ToothClass;
  position: number;
  fill: string;
  stroke: string;
  dashed: boolean;
}) {
  const common = {
    fill,
