          <rect x={4} y={4} width={32} height={32} rx={9} {...common} />
          <path
            d="M20 9v22M9 20h22"
            stroke={stroke}
            strokeOpacity={0.28}
            strokeWidth={1.5}
            strokeLinecap="round"
          />
        </>
